const el = (tag, attrs={}, ...children) => { const node=document.createElement(tag); for(const [key,value] of Object.entries(attrs)){
  if(key==="class") node.className=value; else if(key==="text") node.textContent=value;
  else if(key==="value") node.value=value??""; else if(key==="checked") node.checked=!!value;
  else if(key.startsWith("on")&&typeof value==="function") node.addEventListener(key.slice(2).toLowerCase(),value);
  else if(value!==false&&value!=null) node.setAttribute(key,value===true?"":String(value));
} for(const child of children.flat()) if(child!=null) node.append(child instanceof Node?child:document.createTextNode(String(child))); return node; };
const select = (items,value="",attrs={}) => { const node=el("select",attrs); for(const item of items) node.add(new Option(item.label??item[1],item.value??item[0])); node.value=value??""; return node; };
const button = (text,fn,kind="secondary") => el("button",{type:"button",class:kind,text,onclick:action(fn)});
const field = (text,node) => el("label",{},text,node);
const check = (text,id,checked=false) => field(text,el("input",{id,type:"checkbox",checked}));
const fmtSeconds = value => typeof value==="number"&&Number.isFinite(value)?value.toFixed(2)+" s":"未记录";
const fmtBytes = value => typeof value==="number"&&Number.isFinite(value)?(value/1073741824).toFixed(2)+" GB":"未记录";
const compact = value => value==null?"未记录":typeof value==="object"?Object.entries(value).map(([k,v])=>k+"："+String(v)).join(" · "):String(value);
function message(text,error=false){const node=byId("cd-message");node.textContent=text;node.hidden=!text;node.classList.toggle("error",error);}
function action(fn){return async event=>{const target=event?.currentTarget;const disable=target?.tagName==="BUTTON";if(disable){target.disabled=true;target.setAttribute("aria-busy","true");}try{return await fn(event);}catch(error){message(error.message||String(error),true);if(error.status===409)byId("cd-save-state").textContent="磁盘版本已更新，草稿保留。请刷新比较后再保存。";}finally{if(disable){target.disabled=target.dataset.persistDisabled==="true";target.removeAttribute("aria-busy");}}};}
