async function request(path,options={}){const response=await fetch(path.startsWith("/api/")?path:"/api/creative"+path,options);if(!response.ok){let detail;try{detail=(await response.json()).detail;}catch{detail=response.statusText;}const error=Error(typeof detail==="string"?detail:"请求参数无效，请检查填写内容");error.status=response.status;throw error;}return response.json();}
const send=(path,payload,method="POST")=>request(path,{method,headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});
function url(value){if(typeof value!=="string")return "";const parsed=new URL(value,location.origin);if(parsed.origin!==location.origin||!["http:","https:"].includes(parsed.protocol))return "";return parsed.href;}
function download(value,label="下载"){const href=url(value);if(!href)return null;return el("a",{href,class:"secondary",download:true,text:label});}
function offerDownload(value,label){const link=download(value,label);if(link){byId("cd-downloads").prepend(link);message(label+"已准备好。");}}
function number(id,min,max,integer=false){const value=Number(byId(id).value);if(!Number.isFinite(value)||value<min||value>max||(integer&&!Number.isInteger(value)))throw Error("请检查数字输入："+byId(id).closest("label")?.firstChild?.textContent);return value;}
function seed(id="cd-base-seed",label="基础种子"){const value=byId(id).value.trim();if(!/^[0-9]{1,20}$/.test(value)||BigInt(value)>18446744073709551615n)throw Error(label+"请输入 0–18446744073709551615 的整数。");return value;}
