function options({selected=false,failed=false,suspect=false}={}){const chosen=selected?[...state.selected]:undefined;if(selected&&!chosen.length)throw Error("请先在台词表勾选要重做的行。");return {generation_mode:byId("cd-generation-mode").value,takes_per_line:number("cd-takes",1,32,true),base_seed:seed(),
  sampling:sampling(),lookahead:number("cd-lookahead",0,100,true),retry_failed:true,only_failed:failed,suspect_only:suspect,force:failed?false:suspect?true:byId("cd-force").checked,...(chosen?{line_ids:chosen}:{}),quality_after:byId("cd-quality-after").checked,max_quality_retries:qualityRetries()};}
