  byId("cd-record-audio").src=url(result.source_audio);let lines=result.lines?.length?result.lines:(result.segments||[]).map((region,index)=>({line_id:"R"+String(index+1).padStart(2,"0"),role:region.role||"旁白",original_text:"",start_seconds:region.start,end_seconds:region.end}));
