function region(){const start=number("cd-region-start",0,86400),end=number("cd-region-end",.001,86400),duration=state.recording?.duration_seconds||state.waveDuration;if(end<=start||duration&&end>duration+.02)throw Error("请选择位于原录音内的有效起止时间。");return {start,end};}
