async function regionToVoice(){const chosen=region(),row=recordingRows()[state.activeRecordIndex];state.referenceOrigin=null;state.referenceInputId=state.recording?.input_id||null;state.referenceFile=state.referenceInputId?null:await selectedRecordingFile();byId("cd-ref-file").value="";byId("cd-ref-source").textContent="来自录音："+(state.recording?.name||state.referenceFile?.name||"录音")+" · "+chosen.start.toFixed(2)+"–"+chosen.end.toFixed(2)+" 秒";byId("cd-ref-start").value=String(chosen.start);byId("cd-ref-end").value=String(chosen.end);byId("cd-ref-text").value=row?.original_text||"";byId("cd-ref-name").value=row?.role||"";setTab("library");byId("cd-reference-card").scrollIntoView({behavior:"smooth"});message("片段已带入参考表单。选择已有音色可保存同角色的新版本，编码后原音与片段都会保留。");}
async function recordingToProject(){const rows=recordingRows().filter(row=>row.original_text.trim());if(!rows.length)throw Error("请先校正至少一条准确台词。");for(const row of rows)if(!Number.isFinite(row.start_seconds)||!Number.isFinite(row.end_seconds)||row.end_seconds<=row.start_seconds)throw Error("请先校正每条台词的起止时间。");
  const result=await send("/script/preview",{lines:rows.map((row,index)=>({...row,line_id:"R"+String(index+1).padStart(2,"0"),target_seconds:row.end_seconds-row.start_seconds})),dictionary:dictionary()});state.backup=readRows();byId("cd-restore-draft").hidden=!state.backup.length;renderLines(result.lines);markDirty();setTab("projects");message("已把校正后的录音台词导入草稿，保存后即可选角与生成。");}
